preConditionHook:
// HAS THE CORRECTION RUN LONG ENOUGH? After a three-push or wedge extreme, the
// correction counts as complete only once it has lasted at least a fraction of
// the pattern's OWN bar count. R17-15 gives about half as many bars as the
// wedge (the default) and T24-09 a third or so; one rule, one input.
//
// R17-15 also asks for two clear legs in the correction. That is the leg
// counter, an AND-ed pane of its own (HighLowBarCount), not part of this test.
//
// correctionBars is the pattern extreme's own BARS-AGO count -- the extreme is
// the most recent pivot, so the bars since it and its index are the same
// number. patternBars is the distance from the first push to that extreme.
// Both fall straight out of the pivot scan, with no bar-number bookkeeping.
//
// MIRRORED, not identical on both sides, though the merged slice recorded the
// rule as same-sided: the extreme of a three-push BOTTOM is a swing low and of
// a three-push TOP a swing high, so the long pane reads the low pivots and the
// short the high ones. The ratio is the same on both sides; the series is not.
//
// patternBars must be positive -- with one pivot, or pushCount 1, there is no
// pattern to measure against and the test is meaningless rather than trivially
// true. The fraction is compared, never divided, so nothing can divide by
// zero; the comparison is against a bar COUNT scaled by a fraction, so it is
// written el_ge rather than a bare >= to keep the relational tolerance the
// twin's own comparison carries.
//
// Pivot scan as in ThreePushPattern, inlined; the register lists Occurrence 3+
// as unmeasured, so the first push is found by hand. MEASURED
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT
// OR ABOVE the swingStrength OLDER bars and STRICTLY ABOVE the swingStrength
// NEWER bars -- bars-ago indexing, so the newer bars are the smaller k and
// take el_gt / el_lt, the older el_ge / el_le; confirmation lag exactly
// swingStrength bars; candidate offsets swingStrength .. lookbackBars - 1, the
// neighbourhood reaching swingStrength bars past the window, so the deepest
// bar touched is lookbackBars - 1 + swingStrength. No early break, as the
// twin.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)swingStrength;
pivWindow = (int)lookbackBars;
nHiPiv = 0;
nLoPiv = 0;
hiBar1 = -1;
hiBar2 = -1;
hiBar3 = -1;
loBar1 = -1;
loBar2 = -1;
loBar3 = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHiPiv < 3) {
        nHiPiv = nHiPiv + 1;
        if (nHiPiv == 1) hiBar1 = j;
        if (nHiPiv == 2) hiBar2 = j;
        if (nHiPiv == 3) hiBar3 = j;
    }
    if (okLo && nLoPiv < 3) {
        nLoPiv = nLoPiv + 1;
        if (nLoPiv == 1) loBar1 = j;
        if (nLoPiv == 2) loBar2 = j;
        if (nLoPiv == 3) loBar3 = j;
    }
}
needP = (int)pushCount;
if (needP < 1) needP = 1;
if (needP > 3) needP = 3;
hiBarP = hiBar3;
loBarP = loBar3;
if (needP == 1) { hiBarP = hiBar1; loBarP = loBar1; }
if (needP == 2) { hiBarP = hiBar2; loBarP = loBar2; }
hiPatternBars = hiBarP - hiBar1;
loPatternBars = loBarP - loBar1;
adequateLo = (nLoPiv >= needP) && (loPatternBars > 0) && el_ge((double)loBar1, minCorrectionFraction * (double)loPatternBars);
adequateHi = (nHiPiv >= needP) && (hiPatternBars > 0) && el_ge((double)hiBar1, minCorrectionFraction * (double)hiPatternBars);
